#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <algorithm>

int main() {
    // Generate primes up to 6000
    std::vector<int> primes;
    for (int candidate_number = 2; candidate_number < 6000; ++candidate_number) {
        bool is_prime_candidate = true;
        for (int known_prime : primes) {
            if (known_prime * known_prime > candidate_number) {
                break;
            }
            if (candidate_number % known_prime == 0) {
                is_prime_candidate = false;
                break;
            }
        }
        if (is_prime_candidate) {
            primes.push_back(candidate_number);
        }
    }

    // Function to get prime factors map
    auto get_prime_factors_map = [&](int n) {
        std::unordered_map<int, int> factors_map;
        for (int prime : primes) {
            if (prime * prime > n) {
                break;
            }
            if (n % prime == 0) {
                int count = 0;
                while (n % prime == 0) {
                    n /= prime;
                    ++count;
                }
                factors_map[prime] = count;
            }
        }
        if (n > 1) {
            factors_map[n] = 1;
        }
        return factors_map;
    };

    // Function to list all factors
    auto list_all_factors = [&](int n) {
        auto prime_factors = get_prime_factors_map(n);
        std::vector<long long> factors_list = {1};
        for (const auto& pf : prime_factors) {
            int prime = pf.first;
            int power = pf.second;
            std::vector<long long> temp_list;
            for (long long val : factors_list) {
                for (int p = 0; p <= power; ++p) {
                    long long new_val = val;
                    for (int i = 0; i < p; ++i) {
                        new_val *= prime;
                    }
                    temp_list.push_back(new_val);
                }
            }
            factors_list = temp_list;
        }
        return factors_list;
    };

    // Function to compute value
    auto compute_value = [&](int n, int m) {
        std::unordered_map<int, long long> f_dict;
        f_dict[0] = 0;
        f_dict[1] = 1;
        f_dict[2] = 2;
        for (int i = 3; i <= n; ++i) {
            long long val = 2 * f_dict[i - 1];
            for (long long divisor : list_all_factors(i)) {
                if (divisor >= 2 && divisor <= i) {
                    long long term1 = f_dict[i / divisor];
                    long long term2 = f_dict[(i - 1) / divisor];
                    val += (term1 - term2);
                }
            }
            val %= m;
            f_dict[i] = val;
        }
        return f_dict[n];
    };

    int a_input, b_input;
    std::cin >> a_input >> b_input;
    std::cout << compute_value(a_input, b_input) << std::endl;

    return 0;
}
